return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'gu','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-02T07:33:51+00:00','po-revision-date'=>'2026-09-02T07:33:51+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'WordPress માટેનું સંપૂર્ણ કેશિંગ અને ઑપ્ટિમાઇઝેશન એન્જિન: ફુલ-પેજ કેશ, ઑબ્જેક્ટ કેશ, ડેટાબેઝ ક્લીનઅપ અને CSS/JS ઑપ્ટિમાઇઝેશન. જ્યારે તમારું હોસ્ટ પોતાનું કેશ લેયર પૂરું ન પાડતું હોય ત્યારે આ ઇન્સ્ટોલ કરો — Zinn Digital® હોસ્ટિંગ પર તેના બદલે Zinn® Cache ઇન્સ્ટોલ કરો. ફુલ-પેજ કેશિંગ માટે LSCache મોડ્યુલ સાથે LiteSpeed અથવા OpenLiteSpeed સર્વરની જરૂર છે. LiteSpeed Cache પ્લગઇનનું GPLv3 ફોર્ક.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d કલાક','%d hour'=>'%d કલાક','%d minutes'=>'%d મિનિટો','%d minute'=>'%d મિનિટ','Purged All!'=>'બધાને દૂર કર્યા!','Purged the blog!'=>'બ્લોગ ખાલી કરી દીધો છે!','Purged the URL!'=>'URL ડિલીટ થઈ ગઈ!','Purged!'=>'ડિલીટ થઈ ગયું!','Failed to upgrade.'=>'અપગ્રેડ નિષ્ફળ ગયું.','Upgraded successfully.'=>'સફળતાપૂર્વક અપગ્રેડ કર્યું.','Dashboard'=>'ડેશબોર્ડ','OptimaX'=>'ઑપ્ટિમાએક્સ','Presets'=>'પ્રિસેટ્સ','General'=>'સામાન્ય','Cache'=>'કેશ','CDN'=>'સીડીએન','Image Optimization'=>'ઇમેજ ઑપ્ટિમાઇઝેશન','Page Optimization'=>'પેજ ઓપ્ટિમાઇઝેશન','Database'=>'ડેટાબેઝ','Crawler'=>'ક્રોલર','Toolbox'=>'ટૂલબૉક્સ','Cookie Name'=>'કૂક